using System.Text.Json;
using Jobpilot.Application.Abstractions.Places;
using Jobpilot.Domain.Locations;

namespace Jobpilot.Infrastructure.Places;

/// <summary>
/// Reads the embedded places.json (about 2,200 Swedish localities, generated by scripts/generate-places.py from
/// GeoNames, CC BY 4.0) once, on first use. Registered as a singleton.
/// </summary>
public sealed class EmbeddedPlaceDirectory : IPlaceDirectory
{
    private const string ResourceName = "Jobpilot.Infrastructure.Places.places.json";

    private static readonly JsonSerializerOptions _jsonOptions = new(JsonSerializerDefaults.Web);

    private readonly Lazy<IReadOnlyList<Place>> _all = new(Load);

    public IReadOnlyList<Place> All => _all.Value;

    private static IReadOnlyList<Place> Load()
    {
        using var stream = typeof(EmbeddedPlaceDirectory).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource {ResourceName} is missing.");
        var rows = JsonSerializer.Deserialize<PlaceRow[]>(stream, _jsonOptions)
            ?? throw new InvalidOperationException($"Embedded resource {ResourceName} is empty.");

        return [.. rows.Select(row => new Place(
            row.Name,
            row.Municipality,
            Coordinates.Create(row.Latitude, row.Longitude).Value,
            row.Population))];
    }

    private sealed record PlaceRow(string Name, string Municipality, double Latitude, double Longitude, int Population);
}
